ST.xhtml:p:
RTrigger1(CLK := g_bZJogEnableM);
RTRigger2(CLK := g_bZJogCloseM);
RTrigger_Forward(CLK := bJogForwardEnable);
RTrigger_Backward(CLK := bJogBackwardEnable);

IF RTrigger_Forward.Q OR RTrigger_Backward.Q THEN
  nJogState := 2;
END_IF;

IF g_bZAxisTorqueWarn THEN
  bJogForwardEnable := FALSE;
  bJogBackwardEnable := FALSE;
END_IF;  

IF RTrigger1.Q THEN
  g_bZJogEnableM := FALSE;
  IF g_fZJogVelocityM >= 0.0 THEN
    bJogForward := TRUE;
    bJogBackward := FALSE;
    IF g_fZJogVelocityM <> 0.0 THEN
      dTargetVel := g_fZJogVelocityM;
    ELSE
      dTargetVel := g_fZAxisVel;
    END_IF;
  ELSE
    bJogForward := FALSE;
    bJogBackward := TRUE;
    dTargetVel := -g_fZJogVelocityM;
  END_IF;
  nJogState := 1;
END_IF;

IF RTRigger2.Q THEN
  nJogState := 0;
  g_bZJogCloseM := FALSE;
END_IF;

IF bJogFast THEN
  g_ZMoveJog.Mode := 1;
ELSE
  g_ZMoveJog.Mode := 0;
END_IF;

CASE nJogState OF
  0:
    dTargetVel := 0.0;
    bJogForward := bJogForwardEnable;
    bJogBackward := bJogBackwardEnable;
  1:
    nJogState := 1;
  2:
    IF Axis_Z.NCTOPLC.AxisState = 9 THEN
      g_bZFollowOutDone:=FALSE;
      nJogState := 3;
    ELSE
      nJogState := 0;
    END_IF;
  3:
    g_bZFollowClose := TRUE;
    g_nFollowState :=150; 
    IF g_bZFollowOutDone THEN
      g_bZFollowClose := FALSE;
      nJogState := 0;
    END_IF;
END_CASE;

IF g_ZMoveJog.Error OR g_ZMoveJog.Commandaborted THEN
  dTargetVel := 0.0;
  bJogForward := FALSE;
  bJogBackward := FALSE;
  bJogForwardEnable := FALSE;
  bJogBackwardEnable := FALSE;
  nJogState := 0;
END_IF;

g_ZMoveJog.JogForward := bJogForward;
g_ZMoveJog.JogBackwards := bJogBackward;
g_ZMoveJog.Velocity := dTargetVel;


IF g_bPlcResetBuffer THEN
  bJogForward := FALSE;
  bJogBackward := FALSE;
END_IF;
